#include <memory>
#include <iostream>

class Resource {};

int main() {
    std::auto_ptr<Resource> src(new Resource());
    std::cout << "Source valid before copy: " << (src.get() != nullptr) << "\n";

    // Destructive copy operation
    std::auto_ptr<Resource> dest = src;

    std::cout << "Source valid after copy: " << (src.get() != nullptr) << "\n";
    // src is now null and dereferencing it is UB.

    // Assignment restriction
    // dest = new Resource(); // ERROR: Cannot assign raw pointer

    // Correct assignment via temporary wrapper
    dest = std::auto_ptr<Resource>(new Resource()); // OK
}
